={
  "model": "{{$env.GROQ_MODEL || 'llama-3.3-70b-versatile'}}",
  "temperature": 0.1,
  "response_format": { "type": "json_object" },
  "messages": [
    {
      "role": "system",
      "content": "You are an emergency information extraction engine. Extract ONLY explicitly stated info. Return valid JSON with keys: disaster_type, location, people_affected (number), vulnerable_people ({detected: boolean, types: string[]}), immediate_need (string[]), resources_required (string[]), severity (critical|high|medium|low), time_reference, confidence (number), summary."
    },
