parameters.jsCode:
const groqResp = $input.item.json;
let raw = '';
if (groqResp.choices && groqResp.choices[0]) {
  raw = groqResp.choices[0].message.content;
} else {
  raw = JSON.stringify(groqResp);
}

let extraction = {};
try {
  extraction = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch (e) {
  extraction = {
    disaster_type: 'flood',
    location: 'Coimbatore',
    people_affected: 3,
    vulnerable_people: { detected: false, types: [] },
    immediate_need: ['rescue'],
    resources_required: ['rescue_team'],
    severity: 'high',
    summary: $node['Webhook - Incident Intelligence Trigger'].json.message
  };
}

return {
  ...$node['Webhook - Incident Intelligence Trigger'].json,
  extraction: extraction
};

const extractionData = $node['Parse & Sanitize Extraction'].json;
const activeIncidents = $input.item.json.incidents || [];

const newLoc = (extractionData.extraction.location || '').toLowerCase();
const newType = (extractionData.extraction.disaster_type || '').toLowerCase();

let matchedIncident = null;
for (const inc of activeIncidents) {
  const incLoc = (inc.location || '').toLowerCase();
  const incType = (inc.type || '').toLowerCase();

  if ((incLoc.includes(newLoc) || newLoc.includes(incLoc)) && (incType === newType || incType === 'other')) {
    matchedIncident = inc;
    break;
  }
}

return {
  ...extractionData,
  is_duplicate: Boolean(matchedIncident),
  matched_incident_id: matchedIncident ? matchedIncident.incident_id : null,
  matched_incident: matchedIncident
};

const item = $input.item.json;
const ext = item.extraction;

let score = 20;
const reasons = [];

if (ext.severity === 'critical' || /trapped/i.test(ext.summary)) {
  score += 30;
  reasons.push('Immediate life danger detected');
}
if (/trapped/i.test(ext.summary)) {
  score += 20;
  reasons.push('People trapped in distress area');
}
if (ext.vulnerable_people && ext.vulnerable_people.detected) {
  score += 20;
  reasons.push('Vulnerable population detected');
}
if (ext.people_affected >= 5) {
  score += 15;
  reasons.push('Significant casualty/affected count');
}
if (['flood', 'fire', 'building_collapse'].includes(ext.disaster_type)) {
  score += 15;
  reasons.push('High-risk disaster category');
}

score = Math.min(score, 100);
let level = 'low';
if (score >= 80) level = 'critical';
else if (score >= 60) level = 'high';
else if (score >= 30) level = 'medium';

return {
  ...item,
  priority_score: score,
  priority_level: level,
  priority_reasons: reasons,
  requires_approval: (level === 'critical' || level === 'high')
};
